#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <climits>
using namespace std;

typedef long long ll;
const int MOD=1000000007;
const ll LIM=LLONG_MAX-(ll)MOD*MOD;
using Matrix = vector<vector<int>>;

int gcd(int a,int b) { return b==0?a:gcd(b,a%b); }

ll n; int base;

void matrixMultiply(const Matrix &A, const Matrix &B, Matrix &C, int size) {
    for(int i=0; i<=size; ++i)
        for(int j=0; j<=size; ++j) {
            ll sum=0;
            for(int k=0; k<=size; ++k) {
                if(sum>LIM) sum%=MOD;
                sum+= (ll)A[i][k]*B[k][j];
            }
            C[i][j]=sum%MOD;
        }
}

void copyMatrix(const Matrix &A, Matrix &B) {
    B=A;
}

void printMatrix(const Matrix &A) {
    for(auto &row : A) {
        for(auto &val : row)
            printf("%2d ", val);
        printf("\n");
    }
}

int main() {
    cin>>n>>base;
    int size=base;
    Matrix mat[60][32], have, tmp;
    for(int i=0; i<size; ++i)
        for(int j=0; j<=size; ++j)
            for(int k=0; k<=size; ++k)
                mat[0][i][j][k]= (i==j || j==k) ? 1 : 0;

    int ci=0, cj=0;
    ll step=1;
    while(step<=n/size) {
        ++ci; step*=size;
    }

    for(int i=1; i<=ci; ++i)
        for(int j=0; j<size; ++j) {
            for(int k=0; k<=size; ++k)
                for(int l=0; l<=size; ++l)
                    mat[i][j][k][l]= (k==l) ? 1 : 0;
            for(int k=0; k<size; ++k) {
                matrixMultiply(mat[i][j], mat[i-1][(j+k)%size], tmp, size);
                copyMatrix(tmp, mat[i][j]);
            }
        }

    for(int k=0; k<=size; ++k)
        for(int l=0; l<=size; ++l)
            have[k][l]= (k==l) ? 1 : 0;

    for(; ci>=0; --ci, step/=size) {
        int times= (n/step)%size;
        for(int x=0; x<times; ++x) {
            matrixMultiply(have, mat[ci][cj], tmp, size);
            copyMatrix(tmp, have);
            if(++cj>=size) cj-=size;
        }
    }

    int result=0;
    for(int k=0; k<=size; ++k) {
        result+=have[k][size];
        if(result>=MOD) result-=MOD;
    }
    cout<<result<<endl;
    return 0;
}
